            <p>此信通常题为《与王介甫书》，收入《司马温公集》，是熙宁三年司马光致王安石长篇书信中的一段。其时司马光任翰林学士，屡以辞官相争；王安石则在中书主持新法，青苗、免役次第推行。书信往还因此不只是私谊通信，而是两位执政层官员在制度方向上的正式交锋。</p>
