            <p>“棉花铺遍野”一句最值得注意。元代棉花种植自岭南、闽广北传，经江南推广至山东、河南，到元中期已进入华北平原。它改变了衣料结构，也改变了农家生计，纺织成为副业收入，赋税中开始出现棉布折纳。作者把这一变化写作路边所见，恰说明棉作在北方已是寻常景象。</p>
