            <p>引文出自《宋会要辑稿·职官》门类，属制度条文一类，规定的是进奏院的报送节奏：常规事务五日一报，边报每日上报，军情紧急则不拘常限随时入递。这类文字看似枯燥，却把信息传递的时间分成等级，说明朝廷对消息时效的判断本身就是一种政治安排。</p>
