            <p>引文出自《明史·食货志》对一条鞭法内容的概括，语句几乎是制度条文的转写，可与《张文忠公全集》中相关题奏参看。它描述的不是某一年的诏令，而是嘉靖以来在南方若干州县陆续试行、至万历初年由中央推行全国的一整套办法，因此各地实施程度并不整齐。</p>
