            <p>白江口在今韩国锦江入海处，663年唐罗联军与倭国、百济残余势力在此决战。刘仁轨以水军统领的身份主持战事，唐军战船据守江口，倭军船数虽多而队形拥挤，四战之后火攻奏效。此役之后，百济复兴的努力彻底断绝，倭国在此后近千年间不再向朝鲜半岛大规模用兵，东北亚的政治格局由此定型。</p>
