        date: "2026-08-01",
        tags: ["唐代", "海上交通", "日记"],
        excerpt: "“十四日，海面茫茫，不见山岛。船头诸人皆忧，恐失航路。幸而有北风，船行如飞，日行百余里。”",
        commentary: `
            <p>日本求法僧圆仁的《入唐求法巡礼行记》，与玄奘《大唐西域记》、马可·波罗游记并称东方三大旅行记。圆仁于838年随遣唐使入唐，滞留近十年，以日记体记录了一路的见闻。这段关于海上航行的文字，保存了九世纪东亚航海技术、气象知识与海路险阻的珍贵细节。更难得的是，他的日记视野不止于佛寺，还记录了唐末地方社会、乡村经济与武宗灭佛等重大事件，是研究唐代社会史的独特史料。</p>
            <p>圆仁于承和五年随最后一批遣唐使出发，四船渡海，途中遇风漂散，他本人在扬州登岸，其后北上巡礼五台山，入长安，又逢会昌灭佛，被迫还俗，最终于大中元年搭新罗商船归国。卷四所记正是灭佛前后的见闻与这段归程，故其笔下的海面既是地理空间，也是政治变局之后的退路。</p>
            <p>引文中的几处用语值得细读。海面茫茫、不见山岛，说的是地文航海的条件：九世纪的东亚船只主要靠山形、岛屿与水色辨认航路，一旦失去地标，船上众人便失去方位感。幸而有北风、船行如飞，则点出风向对航程的决定作用，顺风时一日可行百余里，逆风时只能停泊待信。日行百余里既是速度记录，也是当时航海技术的上限。</p>
            <p>这类日记的史料价值，在于它把制度史里看不见的日常经验保留下来：候风、祭神、修补船具、与沿岸州县交涉。局限则有两层，一是日记出于僧侣之笔，关注点多在寺院与戒律，对商贸与航路的技术细节只是顺带提及；二是现存文本经日本寺院长期传抄，个别字句存在异文，使用时需先作校勘。至于东方三大旅行记的并称，是后世的概括，不宜当作当时人的自我定位。</p>
        `
