        date: "2026-07-28",
        tags: ["隋代", "高句丽", "原始史料"],
        excerpt: "“高句丽，在辽东之东千里，南接朝鲜、濊貊，东据大海，西与燕接。其国东西二千里，南北千余里，都于平壤城，亦曰长安城。”",
        commentary: `
            <p>《隋书·东夷传》是系统记载高句丽地理、制度与隋朝关系的第一手文献。这段文字点明了高句丽的四至方位与都城所在，是复原其疆域的基础史料。隋唐两代对高句丽的征伐，始终与辽东领土争端纠缠在一起——隋炀帝三征高句丽更直接动摇了隋朝的统治根基。透过这条史料，可以切入一个更大的问题：为何一个半岛政权能够成为大一统王朝的远征目标？高句丽的城池防御、山地地形与政权韧性，都是关键变量。</p>
            <p>《隋书》的纪传部分由魏徵、令狐德棻等奉敕修撰，贞观年间成书，其《东夷传》依次排列高句丽、百济、新罗、倭国等条，体例沿袭四夷传的传统。这类传目所依据的材料，包括隋代的起居注、国史以及使臣的见闻，因此对隋代东北亚关系的记载相对贴近，但仍属唐初的官方编纂，带有取舍。</p>
            <p>引文的写法是典型的地理程式：先定方位，再记四至，最后落到都城。在辽东之东千里，是以中原为坐标的方位判断，里数不可径作精确里程；南接朝鲜、濊貊，其中朝鲜指古朝鲜故地，濊貊则是族群泛称，二者提示高句丽南界族群混杂。都于平壤城、亦曰长安城一句尤可注意，平壤自长寿王迁都后成为政治中心，这一别名则反映该城在高句丽内部的多重身份。</p>
            <p>这条材料能说明的，是中原王朝对高句丽的地理认知框架，以及辽东在战略想象中所占的位置。它的局限也很清楚：描述是静态的，不反映疆域伸缩；四至表述以中原为中心，会抹平边界的模糊与浮动；里数往往夸张。若要讨论疆域与城防，还需结合好太王碑、高句丽城址考古，以及《周书》《北史》的平行记载。</p>
        `
